<a class="back" href="javascript:history.back()">← Previous</a><h1>Record sale</h1><?php $errors=session()->getFlashdata('errors')??[]; if($errors): ?><div class="flash error"><?= esc(implode(' ', $errors)) ?></div><?php endif ?><form method="post"><?= csrf_field() ?><label>Product<select name="product_id" required><option value="">Choose a product</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>" <?= old('product_id')==$p['id']?'selected':'' ?>><?= esc($p['name']) ?> — $<?= number_format($p['price'],2) ?> (<?= $p['stock_quantity'] ?> in stock)</option><?php endforeach ?></select></label><label>Customer (optional)<select name="customer_id"><option value="">Walk-in customer</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>"><?= esc($c['full_name']) ?></option><?php endforeach ?></select></label><label>Quantity<input type="number" min="1" name="quantity" value="<?= esc(old('quantity',1)) ?>" required></label><button>Record sale</button> <a class="btn secondary" href="/sales">Cancel</a></form>
